<?php declare(strict_types=1);namespace StudPulse\Http;use StudPulse\Database\DB;use StudPulse\Domain\{Access,Input,Notices};use StudPulse\Security\Auth;use StudPulse\Bars\{BarsJournal,BarsOfficialAdapter,ProviderFactory};use StudPulse\Integrations\MpeiSchedule;final class HeadmanController{public function localRoster(Auth$a):array{$m=$a->journal();return['source'=>'studpulse_members_not_official_roster','items'=>DB::all("SELECT DISTINCT u.id,u.display_name FROM group_memberships gm JOIN users u ON u.id=gm.user_id AND u.status='active' WHERE gm.group_id=? AND gm.term_id=? AND gm.valid_from<=UTC_TIMESTAMP(6) AND gm.valid_to>UTC_TIMESTAMP(6) ORDER BY u.display_name",[$m['group_id'],$m['term_id']])];}public function classes(Auth$a):array{$m=$a->journal();if(!empty($m['url'])){return['items'=>[],'attendanceDrafts'=>[],'period'=>$m['period'],'role'=>$m['role'],'journalUrl'=>$m['url'],'officialWrites'=>'bars'];}$period=$this->term($m);$items=DB::all("SELECT * FROM headman_class_drafts WHERE group_id=? AND term_id=? ORDER BY payload_json->>'$.start_at' DESC LIMIT 1000",[$m['group_id'],$m['term_id']]);$marks=DB::all("SELECT class_draft_id,status,revision,marks_json,roster_source FROM (
            SELECT class_draft_id,status,revision,marks_json,roster_snapshot->>'$.source' AS roster_source,ROW_NUMBER() OVER(PARTITION BY class_draft_id ORDER BY revision DESC,id DESC) AS seq
            FROM headman_attendance_drafts WHERE group_id=? AND term_id=?
        ) recent WHERE seq=1",[$m['group_id'],$m['term_id']]);return['items'=>$items,'attendanceDrafts'=>$marks,'period'=>$period,'role'=>$m['role'],'journalUrl'=>null,'officialWrites'=>'BLOCKED_EXTERNAL'];}private function term(array$membership):array{return DB::one('SELECT academic_year,season,begins_at,ends_at FROM terms WHERE id=? AND archived_at IS NULL',[$membership['term_id']])??throw new ApiError(404,'TERM_REQUIRED','Семестр не найден.');}public function roster(Auth$a):array{$m=$a->journal();$p=ProviderFactory::make($a);$url=$m['url']??('https://bars.mpei.ru'.BarsJournal::GROUPS);if($p instanceof BarsOfficialAdapter){try{$journal=$p->headmanJournal();$url=$journal['url'];if($journal['items']){return['items'=>$journal['items'],'source'=>'bars','journalUrl'=>$url];}}catch(ApiError){}}return[...$this->localRoster($a),'journalUrl'=>$url];}public function importSchedule(Auth$a,Request$r):array{$m=$a->journal();$period=$this->term($m);$first=Input::day($r->body['from']??null);$last=Input::day($r->body['to']??$r->body['from']??null);$days=$first->diff($last);if($days->invert||$days->days>=31||$first->format('Y-m-d')<$period['begins_at']||$last->format('Y-m-d')>$period['ends_at']){throw new ApiError(422,'JOURNAL_RANGE','Выберите до 31 дня в пределах семестра.');}$p=ProviderFactory::make($a);$only=$r->body['lessonId']??null;if($only!==null){$only=$p instanceof BarsOfficialAdapter?Input::lessonId($only):Input::id($only);}$utc=new \DateTimeZone('UTC');$from=$first->setTimezone($utc)->format('Y-m-d H:i:s');$to=$last->modify('+1 day')->setTimezone($utc)->format('Y-m-d H:i:s');$schedule=$p instanceof BarsOfficialAdapter?MpeiSchedule::forGroup($m['canonical_code'],$from,$to):$p->getMySchedule($from,$to);$items=[];foreach($schedule->items as$lesson){if($lesson['status']==='cancelled'||($only!==null&&$only!==$lesson['id'])){continue;}$ruz=$lesson['source']==='ruz';$localId=$ruz?null:Access::meeting($a,Input::id($lesson['id']),$m)['id'];$ruzId=$ruz?$lesson['id']:null;DB::run('INSERT INTO headman_class_drafts(id,group_id,term_id,creator_user_id,source_meeting_id,ruz_lesson_id,payload_json) VALUES(?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE id=id',[DB::id(),$m['group_id'],$m['term_id'],$a->user['id'],$localId,$ruzId,json_encode($lesson,JSON_THROW_ON_ERROR)]);$key=$ruz?'ruz_lesson_id':'source_meeting_id';$items[]=DB::one("SELECT * FROM headman_class_drafts WHERE group_id=? AND term_id=? AND $key=?",[$m['group_id'],$m['term_id'],$lesson['id']]);}if($only!==null&&!$items){throw new ApiError(404,'LESSON_NOT_FOUND','Пара не найдена в расписании группы.');}if($items){Access::audit($a,'headman.schedule_import','draft',$items[0]['id'],$r->correlationId,$m['group_id']);}return['items'=>$items];}public function createClass(Auth$a,Request$r):array{$m=$a->journal();$json=json_encode($this->classFields($r->body,$this->term($m))+['source'=>'manual'],JSON_THROW_ON_ERROR);DB::one('SELECT id FROM academic_groups WHERE id=? FOR UPDATE',[$m['group_id']]);$existing=DB::one('SELECT id FROM headman_class_drafts WHERE group_id=? AND term_id=? AND source_meeting_id IS NULL AND ruz_lesson_id IS NULL AND payload_json=CAST(? AS JSON)',[$m['group_id'],$m['term_id'],$json]);if($existing){return['id'=>$existing['id']];}$id=DB::id();DB::run('INSERT INTO headman_class_drafts(id,group_id,term_id,creator_user_id,payload_json) VALUES(?,?,?,?,?)',[$id,$m['group_id'],$m['term_id'],$a->user['id'],$json]);Access::audit($a,'headman.class_create','draft',$id,$r->correlationId,$m['group_id']);return['id'=>$id];}public function updateClass(Auth$a,Request$r,string$id):array{$m=$a->journal();$revision=Input::revision($r->body);$fields=$this->classFields($r->body,$this->term($m));$draft=DB::one('SELECT payload_json,state,revision FROM headman_class_drafts WHERE id=? AND group_id=? AND term_id=? FOR UPDATE',[$id,$m['group_id'],$m['term_id']]);if(!$draft){throw new ApiError(404,'NOT_FOUND','Пара не найдена.');}if($draft['state']!=='local_draft'||(int)$draft['revision']!==$revision){throw new ApiError(409,'VERSION_CONFLICT','Запись изменилась. Обновите журнал.');}$lesson=array_replace(json_decode($draft['payload_json'],true,32,JSON_THROW_ON_ERROR),$fields);DB::run('UPDATE headman_class_drafts SET payload_json=?,revision=revision+1 WHERE id=?',[json_encode($lesson,JSON_THROW_ON_ERROR),$id]);Access::audit($a,'headman.class_edit','draft',$id,$r->correlationId,$m['group_id']);return['id'=>$id,'revision'=>$revision+1];}private function classFields(array$input,array$period):array{$day=Input::day($input['date']??null)->format('Y-m-d');$begin=Input::text($input,'start',5);$end=Input::text($input,'end',5);$timePattern='/^(?:[01][0-9]|2[0-3]):[0-5][0-9]$/D';if($day<$period['begins_at']||$day>$period['ends_at']||!preg_match($timePattern,$begin)||!preg_match($timePattern,$end)||$begin>=$end){throw new ApiError(422,'JOURNAL_RANGE','Укажите дату в пределах семестра и время окончания после начала пары.');}$utc=new \DateTimeZone('UTC');$time=static fn(string$hhmm):string=>(new \DateTimeImmutable($day.'T'.$hhmm.':00+03:00'))->setTimezone($utc)->format('Y-m-d H:i:s');return['subject_title'=>Input::text($input,'title',180),'class_type'=>Input::text($input,'type',40),'teacher_name'=>Input::text($input,'teacher',120,false),'official_room_code'=>Input::text($input,'room',40,false),'subgroup_name'=>Input::text($input,'subgroup',40,false),'start_at'=>$time($begin),'end_at'=>$time($end),];}public function draft(Auth$a,Request$r):array{$m=$a->journal();$ids=$r->body['meetingIds']??[];if(!is_array($ids)||count($ids)<1||count($ids)>20){throw new ApiError(422,'VALIDATION','Выберите от 1 до 20 занятий');}$created=[];foreach($ids as$id){$meeting=Access::meeting($a,Input::id($id),$m);$did=DB::id();DB::run('INSERT IGNORE INTO headman_class_drafts(id,group_id,term_id,creator_user_id,source_meeting_id,payload_json) VALUES(?,?,?,?,?,?)',[$did,$m['group_id'],$m['term_id'],$a->user['id'],$id,json_encode($meeting,JSON_THROW_ON_ERROR)]);$created[]=DB::one('SELECT * FROM headman_class_drafts WHERE group_id=? AND term_id=? AND source_meeting_id=?',[$m['group_id'],$m['term_id'],$id]);}Access::audit($a,'headman.local_drafts','draft',$created[0]['id'],$r->correlationId,$m['group_id']);return['items'=>$created,'message'=>'Локальные черновики. В БАРС ничего не отправлено.'];}public function attendance(Auth$a,Request$r):array{$m=$a->journal();$id=Input::id($r->body['classDraftId']??null);$draft=DB::one('SELECT * FROM headman_class_drafts WHERE id=? AND group_id=? AND term_id=? FOR UPDATE',[$id,$m['group_id'],$m['term_id']]);if(!$draft){throw new ApiError(404,'NOT_FOUND','Черновик не найден');}if($draft['state']!=='local_draft'){throw new ApiError(409,'CLASS_LOCKED','Запись закрыта для редактирования.');}if(($r->body['classRevision']??null)!==(int)$draft['revision']){throw new ApiError(409,'VERSION_CONFLICT','Данные пары изменились. Откройте её ещё раз.');}$source=($r->body['source']??'')==='bars'?$this->roster($a):$this->localRoster($a);if(($r->body['source']??$source['source'])!==$source['source']){throw new ApiError(409,'ROSTER_CHANGED','Список группы изменился. Откройте пару ещё раз.');}$roster=$source['items'];$marks=$r->body['marks']??[];if(!is_array($marks)||!$roster||count($marks)>count($roster)){throw new ApiError(422,'VALIDATION','Некорректные отметки');}$allowed=array_column($roster,'id');foreach($marks as$user=>$mark){if(!in_array($user,$allowed,true)||!in_array($mark,['present','absent','unmarked'],true)){throw new ApiError(422,'INVALID_MARK','Проверьте список и отметки.');}}$previous=DB::one("SELECT id,revision,status,roster_snapshot->>'$.source' AS roster_source FROM headman_attendance_drafts WHERE class_draft_id=? ORDER BY revision DESC,id DESC LIMIT 1",[$id]);$revision=(int)($previous['revision']??0);if(($r->body['revision']??null)!==$revision||($previous['status']??'')==='submitted'){throw new ApiError(409,'VERSION_CONFLICT','Отметки уже изменены. Откройте пару ещё раз.');}if(!empty($previous['roster_source'])&&$previous['roster_source']!==$source['source']){throw new ApiError(409,'ROSTER_CHANGED','Для этой пары нужен исходный список группы.');}$status=count($marks)===count($roster)&&!in_array('unmarked',$marks,true)?'recorded':'local_draft';$snapshot=json_encode(['source'=>$source['source'],'items'=>$roster],JSON_THROW_ON_ERROR);$json=json_encode($marks,JSON_FORCE_OBJECT|JSON_THROW_ON_ERROR);$did=$previous['id']??DB::id();if($previous){DB::run('UPDATE headman_attendance_drafts SET roster_snapshot=?,marks_json=?,status=?,revision=revision+1 WHERE id=?',[$snapshot,$json,$status,$did]);}else{DB::run('INSERT INTO headman_attendance_drafts(id,group_id,term_id,class_draft_id,creator_user_id,roster_snapshot,marks_json,status) VALUES(?,?,?,?,?,?,?,?)',[$did,$m['group_id'],$m['term_id'],$id,$a->user['id'],$snapshot,$json,$status]);}if($status==='recorded'){DB::run("UPDATE notifications n JOIN group_memberships gm ON gm.user_id=n.recipient_user_id AND gm.group_id=? AND gm.term_id=? SET n.read_at=COALESCE(n.read_at,UTC_TIMESTAMP(6)) WHERE n.related_type='journal' AND n.related_id=?",[$m['group_id'],$m['term_id'],$id]);}Access::audit($a,'headman.attendance_save','draft',$id,$r->correlationId,$m['group_id']);return['id'=>$did,'status'=>$status,'revision'=>$revision+1,'message'=>'Отметки сохранены в StudPulse.'];}public function submit(Auth$a,Request$r,bool$attendance=false):array{$a->journal();if(($r->body['confirmed']??false)!==true){throw new ApiError(422,'CONFIRM_REQUIRED','Требуется явное подтверждение');}$p=ProviderFactory::make($a);if($attendance){$p->submitOfficialAttendance(Input::text($r->body,'classId',100),$r->body['marks']??[],$r->header('Idempotency-Key'));}else{$p->createOfficialClasses($r->body,$r->header('Idempotency-Key'));}throw new ApiError(503,'BLOCKED_EXTERNAL','Официальная запись недоступна');}public function announcements(Auth$a):array{$m=$a->group();$rows=DB::all('SELECT n.*,u.display_name AS author_name FROM group_announcements n JOIN users u ON u.id=n.author_user_id WHERE n.group_id=? AND n.term_id=? AND n.deleted_at IS NULL ORDER BY n.created_at DESC LIMIT 50',[$m['group_id'],$m['term_id']]);[$materialScope,$materialParams]=Access::materialReadScope($a);$files=DB::all("SELECT am.announcement_id,m.id,m.title FROM announcement_materials am JOIN group_announcements n ON n.id=am.announcement_id JOIN materials m ON m.id=am.material_id
            WHERE n.group_id=? AND n.term_id=? AND n.deleted_at IS NULL AND m.deleted_at IS NULL AND $materialScope",[$m['group_id'],$m['term_id'],...$materialParams]);foreach($rows as&$row){$row['attachments']=array_values(array_filter($files,fn($f)=>$f['announcement_id']===$row['id']));}return['items'=>$rows];}public function announce(Auth$a,Request$r):array{$m=$a->headman();$id=DB::id();$subject=Access::subject($a,Input::id($r->body['subjectId']??null));DB::run('INSERT INTO group_announcements(id,group_id,term_id,author_user_id,title,body,subject_id,related_at) VALUES(?,?,?,?,?,?,?,?)',[$id,$m['group_id'],$m['term_id'],$a->user['id'],Input::text($r->body,'title'),Input::text($r->body,'body',20000),$subject['id']??null,Input::date($r->body['relatedAt']??null)]);Notices::group($m,'announcement','Новое объявление старосты','announcement',$id);Access::audit($a,'headman.announce','announcement',$id,$r->correlationId);return['id'=>$id];}public function updateAnnouncement(Auth$a,Request$r,string$id):array{$m=$a->headman();$n=DB::one('SELECT * FROM group_announcements WHERE id=? AND group_id=? AND term_id=? AND deleted_at IS NULL',[$id,$m['group_id'],$m['term_id']]);if(!$n){throw new ApiError(404,'NOT_FOUND','Объявление не найдено');}$subject=Access::subject($a,Input::id($r->body['subjectId']??null));$revision=Input::revision($r->body);if(!DB::run('UPDATE group_announcements SET title=?,body=?,subject_id=?,related_at=?,revision=revision+1,updated_at=UTC_TIMESTAMP(6) WHERE id=? AND revision=?',[Input::text($r->body,'title'),Input::text($r->body,'body',20000),$subject['id']??null,Input::date($r->body['relatedAt']??null),$id,$revision])->rowCount()){throw new ApiError(409,'VERSION_CONFLICT','Объявление уже изменено');}Notices::group($m,'announcement','Объявление старосты обновлено','announcement',$id,$revision+1);Access::audit($a,'headman.announcement.update','announcement',$id,$r->correlationId);return['id'=>$id,'revision'=>$revision+1];}public function attachAnnouncement(Auth$a,Request$r,string$id):array{$m=$a->headman();$n=DB::one('SELECT id FROM group_announcements WHERE id=? AND group_id=? AND term_id=? AND deleted_at IS NULL',[$id,$m['group_id'],$m['term_id']]);if(!$n){throw new ApiError(404,'NOT_FOUND','Объявление не найдено');}$material=Access::material($a,Input::id($r->body['materialId']??null)??'');if($material['visibility']!=='group'||$material['group_id']!==$m['group_id']||$material['term_id']!==$m['term_id']){throw new ApiError(422,'GROUP_REQUIRED','Нужно вложение той же группы и семестра');}DB::run('INSERT IGNORE INTO announcement_materials(announcement_id,material_id) VALUES(?,?)',[$id,$material['id']]);return['attached'=>true];}}